insert into chart_lab_answer_keys (
  drill_id, drill_version, answer_type,
  choices, correct_choice, correct_sequence,
  zones, explanation, common_mistake,
  hints, related_rule
) values
(
    '11111111-1111-1111-1111-111111111101', 1, 'choice',
    '[{"key":"bullish","label":"Bullish"},{"key":"bearish","label":"Bearish"},{"key":"unclear","label":"Unclear"}]'::jsonb, 'bullish', null,
    '[]'::jsonb, 'Each swing high and swing low is higher than the one before it — that is the definition of bullish structure on this timeframe.', 'Focusing on one red candle instead of the overall sequence of highs and lows.',
    ARRAY['Ignore individual candle color — look at the swing points.', 'Compare each swing high to the one before it.']::text[], 'Dayli ICC: 4H sets directional bias before anything else is read.'
  ),
(
    '11111111-1111-1111-1111-111111111102', 1, 'point',
    '[]'::jsonb, null, null,
    '[{"x":0.42,"y":0.32,"radius":0.07,"credit":"full"},{"x":0.65,"y":0.55,"radius":0.06,"credit":"partial"}]'::jsonb, 'The swing high is the candle where price stopped making higher highs and reversed — confirmed one candle later.', 'Marking the highest wick instead of the candle that actually broke the up-sequence.',
    ARRAY['A swing high needs a lower high after it to be confirmed.', 'Look for where bullish delivery transitions to bearish delivery.']::text[], null
  ),
(
    '11111111-1111-1111-1111-111111111103', 1, 'point',
    '[]'::jsonb, null, null,
    '[{"x":0.78,"y":0.22,"radius":0.08,"credit":"full"}]'::jsonb, 'The external range is bounded by the most recent significant swing high and low — this candle set that boundary.', 'Using an internal swing instead of the range-defining swing.',
    ARRAY['The external range is the outermost boundary, not every small swing.']::text[], null
  ),
(
    '11111111-1111-1111-1111-111111111104', 1, 'point',
    '[]'::jsonb, null, null,
    '[{"x":0.55,"y":0.4,"radius":0.07,"credit":"full"}]'::jsonb, 'This level is the most recent 1H structure point price hasn’t yet closed through — the active PIL.', 'Picking an older level that price already closed through and invalidated.',
    ARRAY['The PIL must still be unbroken — check for a candle-body close through it first.']::text[], 'Timeframe roles: 1H confirms structure and the active Pre-Indication Level (PIL).'
  ),
(
    '11111111-1111-1111-1111-111111111105', 1, 'choice',
    '[{"key":"valid_close","label":"Valid candle-body close"},{"key":"wick_only","label":"Wick only"},{"key":"unclear","label":"Unclear"},{"key":"not_yet_confirmed","label":"Not yet confirmed"}]'::jsonb, 'wick_only', null,
    '[]'::jsonb, 'The wick crossed the level, but the candle body closed back below it — no candle-body confirmation, so Indication has not completed.', 'Treating any touch of the level as confirmation instead of requiring a body close.',
    ARRAY['A wick and a candle-body close are not the same thing.', 'Check where the candle body — not the wick — closed relative to the level.']::text[], 'The Golden Rule: no candle closure = no confirmation = no trade, every time.'
  ),
(
    '11111111-1111-1111-1111-111111111106', 1, 'choice',
    '[{"key":"pre_indication","label":"Pre-Indication"},{"key":"indication","label":"Indication"},{"key":"correction","label":"Correction"},{"key":"continuation","label":"Continuation"}]'::jsonb, 'correction', null,
    '[]'::jsonb, 'After Indication confirms, a pullback that has not yet resumed in the indicated direction is Correction — observation only, not an entry trigger.', 'Entering during Correction, mistaking the pullback for a fresh setup.',
    ARRAY['Correction always follows a confirmed Indication.', 'It is not the entry — Continuation is.']::text[], 'Entering during Correction is one of the Walk-Away Conditions.'
  ),
(
    '11111111-1111-1111-1111-111111111107', 1, 'choice',
    '[{"key":"valid","label":"Valid"},{"key":"invalid","label":"Invalid"},{"key":"not_enough_confirmation","label":"Not Enough Confirmation"},{"key":"wait","label":"Wait"}]'::jsonb, 'valid', null,
    '[]'::jsonb, 'A candle-body close resuming the original direction after Correction is exactly what confirms Continuation.', 'Entering on the wick before the candle actually closes.',
    ARRAY['Continuation needs the same candle-body-close standard as Indication.']::text[], 'The Golden Rule applies identically to Continuation as it does to Indication.'
  ),
(
    '11111111-1111-1111-1111-111111111108', 1, 'choice',
    '[{"key":"enter_now","label":"Enter now"},{"key":"wait_for_continuation","label":"Wait for the first retest"},{"key":"chase_current_candle","label":"Chase the current candle"},{"key":"move_to_lower_timeframe","label":"Move to a lower timeframe"}]'::jsonb, 'wait_for_continuation', null,
    '[]'::jsonb, 'Entering before the first retest means chasing price that has already moved — waiting for a retest gives a defined, lower-risk entry.', 'Chasing the continuation candle out of fear of missing the move.',
    ARRAY['A retest gives you a real level to risk against — chasing does not.']::text[], null
  ),
(
    '11111111-1111-1111-1111-111111111109', 1, 'choice',
    '[{"key":"valid","label":"Yes — consolidating"},{"key":"invalid","label":"No — trending"},{"key":"not_enough_confirmation","label":"Not enough data"}]'::jsonb, 'valid', null,
    '[]'::jsonb, 'Repeated overlapping candles with no clear directional swing is the definition of consolidation — a Walk-Away Condition, not a setup.', 'Forcing a directional bias onto sideways price.',
    ARRAY['Look for overlapping candle ranges rather than a clear sequence of higher/lower swings.']::text[], 'Consolidation is one of the six Walk-Away Conditions.'
  ),
(
    '11111111-1111-1111-1111-111111111110', 1, 'choice',
    '[{"key":"enter_now","label":"Enter now"},{"key":"wait_for_continuation","label":"Wait"},{"key":"pass","label":"Pass completely"}]'::jsonb, 'wait_for_continuation', null,
    '[]'::jsonb, 'A wick with no confirmed close isn’t a Walk-Away Condition on its own — it just means the setup isn’t ready yet. Wait for real confirmation before deciding to pass.', 'Passing entirely on a setup that just needs more time to develop.',
    ARRAY['"Wait" and "Pass" are different decisions — one keeps the setup open, one closes it.']::text[], 'Wick through the level without a close is a Walk-Away Condition only when combined with acting on it, not with waiting.'
  ),
(
    '11111111-1111-1111-1111-111111111111', 1, 'sequence',
    '[{"key":"indication","label":"Indication"},{"key":"correction","label":"Correction"},{"key":"continuation","label":"Continuation"},{"key":"retest","label":"Retest"}]'::jsonb, null, ARRAY['indication', 'correction', 'continuation', 'retest']::text[],
    '[]'::jsonb, 'Indication confirms the initial move, Correction is the pullback, Continuation confirms the resumption, and Retest offers the lower-risk entry.', 'Placing Retest before Continuation — a retest only makes sense once Continuation has confirmed.',
    ARRAY['Correction always comes right after Indication, never before it.']::text[], null
  )
on conflict (drill_id, drill_version) do nothing;
